            {OP_STA_IND_Y, 4'b0} + 12'h13: current_micro_word = {UJMP_STEP,       ALU_OP_ADD, 1'b1, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, PC_OP_NOP, REG_MEM,  REG_ZERO, REG_IR_H};
            {OP_STA_IND_Y, 4'b0} + 12'h14: current_micro_word = {UJMP_STEP,       ALU_OP_ADD, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, PC_OP_NOP, REG_IR_L, REG_ZERO, REG_ALE};
            {OP_STA_IND_Y, 4'b0} + 12'h15: current_micro_word = {UJMP_STEP,       ALU_OP_ADD, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, PC_OP_NOP, REG_IR_H, REG_ZERO, REG_AHE};
            {OP_STA_IND_Y, 4'b0} + 12'h16: current_micro_word = {UJMP_FETCH,      ALU_OP_ADD, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, PC_OP_NOP, REG_A,    REG_ZERO, REG_MEM};

            // OP_PHA_IMP
            {OP_PHA_IMP, 4'b0} + 12'h10: current_micro_word = {UJMP_STEP,       ALU_OP_ADD, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, PC_OP_NOP, REG_SP,   REG_ZERO, REG_ALE};
            {OP_PHA_IMP, 4'b0} + 12'h11: current_micro_word = {UJMP_STEP,       ALU_OP_ADD, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, PC_OP_NOP, REG_ONE,  REG_ZERO, REG_AHE};
            {OP_PHA_IMP, 4'b0} + 12'h12: current_micro_word = {UJMP_FETCH,      ALU_OP_ADD, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b1, PC_OP_NOP, REG_A,    REG_ZERO, REG_MEM};

            // OP_PHP_IMP
            {OP_PHP_IMP, 4'b0} + 12'h10: current_micro_word = {UJMP_STEP,       ALU_OP_ADD, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, PC_OP_NOP, REG_SP,   REG_ZERO, REG_ALE};
            {OP_PHP_IMP, 4'b0} + 12'h11: current_micro_word = {UJMP_STEP,       ALU_OP_ADD, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, PC_OP_NOP, REG_ONE,  REG_ZERO, REG_AHE};
            {OP_PHP_IMP, 4'b0} + 12'h12: current_micro_word = {UJMP_FETCH,      ALU_OP_ADD, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b1, PC_OP_NOP, REG_SR,   REG_ZERO, REG_MEM};

            // OP_PLA_IMP
            {OP_PLA_IMP, 4'b0} + 12'h10: current_micro_word = {UJMP_STEP,       ALU_OP_ADD, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, PC_OP_NOP, REG_SP,   REG_ONE,  REG_SP};
            {OP_PLA_IMP, 4'b0} + 12'h11: current_micro_word = {UJMP_STEP,       ALU_OP_ADD, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, PC_OP_NOP, REG_SP,   REG_ZERO, REG_ALE};
            {OP_PLA_IMP, 4'b0} + 12'h12: current_micro_word = {UJMP_STEP,       ALU_OP_ADD, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, PC_OP_NOP, REG_ONE,  REG_ZERO, REG_AHE};
            {OP_PLA_IMP, 4'b0} + 12'h13: current_micro_word = {UJMP_FETCH,      ALU_OP_ADD, 1'b0, 1'b0, 1'b0, 1'b1, 1'b0, 1'b0, 1'b0, PC_OP_NOP, REG_MEM,  REG_ZERO, REG_A};

            // OP_PLP_IMP
            {OP_PLP_IMP, 4'b0} + 12'h10: current_micro_word = {UJMP_STEP,       ALU_OP_ADD, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, PC_OP_NOP, REG_SP,   REG_ONE,  REG_SP};
            {OP_PLP_IMP, 4'b0} + 12'h11: current_micro_word = {UJMP_STEP,       ALU_OP_ADD, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, PC_OP_NOP, REG_SP,   REG_ZERO, REG_ALE};
            {OP_PLP_IMP, 4'b0} + 12'h12: current_micro_word = {UJMP_STEP,       ALU_OP_ADD, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, PC_OP_NOP, REG_ONE,  REG_ZERO, REG_AHE};
            {OP_PLP_IMP, 4'b0} + 12'h13: current_micro_word = {UJMP_FETCH,      ALU_OP_ADD, 1'b0, 1'b1, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, PC_OP_NOP, REG_MEM,  REG_ZERO, REG_ZERO};

            // OP_TAX_IMP
            {OP_TAX_IMP, 4'b0} + 12'h10: current_micro_word = {UJMP_FETCH,      ALU_OP_ADD, 1'b0, 1'b0, 1'b0, 1'b1, 1'b0, 1'b0, 1'b0, PC_OP_NOP, REG_A,    REG_ZERO, REG_X};

            // OP_TAY_IMP
            {OP_TAY_IMP, 4'b0} + 12'h10: current_micro_word = {UJMP_FETCH,      ALU_OP_ADD, 1'b0, 1'b0, 1'b0, 1'b1, 1'b0, 1'b0, 1'b0, PC_OP_NOP, REG_A,    REG_ZERO, REG_Y};

            // OP_TSX_IMP
            {OP_TSX_IMP, 4'b0} + 12'h10: current_micro_word = {UJMP_FETCH,      ALU_OP_ADD, 1'b0, 1'b0, 1'b0, 1'b1, 1'b0, 1'b0, 1'b0, PC_OP_NOP, REG_SP,   REG_ZERO, REG_X};

            // OP_TXA_IMP
            {OP_TXA_IMP, 4'b0} + 12'h10: current_micro_word = {UJMP_FETCH,      ALU_OP_ADD, 1'b0, 1'b0, 1'b0, 1'b1, 1'b0, 1'b0, 1'b0, PC_OP_NOP, REG_X,    REG_ZERO, REG_A};

            // OP_TXS_IMP
            {OP_TXS_IMP, 4'b0} + 12'h10: current_micro_word = {UJMP_FETCH,      ALU_OP_ADD, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, PC_OP_NOP, REG_X,    REG_ZERO, REG_SP};

            // OP_TYA_IMP
            {OP_TYA_IMP, 4'b0} + 12'h10: current_micro_word = {UJMP_FETCH,      ALU_OP_ADD, 1'b0, 1'b0, 1'b0, 1'b1, 1'b0, 1'b0, 1'b0, PC_OP_NOP, REG_Y,    REG_ZERO, REG_A};
 
            default: current_micro_word = 28'h0; 
        endcase
    end
   
    // =========================================================================
    // 3. THE OPCODE MAPPER (Combinational)
    // =========================================================================
    wire [7:0] op = (micro_pc == 12'h02) ? mem_in : ir[7:0]; // Opcode being fetched (not yet in IR)
    
   // 0 Extra Bytes: BRK/RTI/RTS, or ends in 8 or A
    wire needs_zero_extra = (op == 8'h40) || (op == 8'h60) || 
                            ({op[3], op[2], op[0]} == 3'b100);

    // 2 Extra Bytes: JSR (0x20), or ends in 9, C, D, or E
    wire needs_two_extra = (op == 8'h20) || 
                        ((op[3:0] == 4'h9) && (op[4] == 1'b1)) || 
                        (op[3:2] == 2'b11);

    // Default to 1 Extra Byte
    wire needs_one_extra = !(needs_two_extra || needs_zero_extra);

    assign dispatch_address = {op, 4'b0} + 12'h010;

    // =========================================================================
    // 4. THE MICRO-SEQUENCER (Clocked)
    // =========================================================================    
    // Extract the uJump command from the top 3 bits
    wire [2:0] uJump = current_micro_word[MICRO_ROM_WORD_SIZE-1:MICRO_ROM_WORD_SIZE-3];

    reg irq_sync1;
    reg irq_sync2;
    wire irq_active = !irq_sync2;   // synchronised IRQ_n level, active high

    reg  clear_nmi;
    wire nmi_pending;

    dfc64_interrupt_controller nmi_controller(
        .clk(clk),
        .rst_n(rst_n),
        .irq_n(nmi_n),
        .clear_irq(clear_nmi),
        .irq_pending(nmi_pending)
    );

    always @(posedge clk) begin
        if (!rst_n) begin
            irq_sync1 <= 1'b1;
            irq_sync2 <= 1'b1;
        end else begin
            irq_sync1 <= irq_n;
            irq_sync2 <= irq_sync1;
        end
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            `ifdef SIM
                $display("%0t Reset!", $realtime);
            `endif
            micro_pc  <= RESET_MICRO_PC; // On power-up, start at the Fetch Routine
            is_irq    <= 1'b0;
            is_nmi    <= 1'b0;
            clear_nmi <= 1'b0;
        end else begin
            `ifdef SIM
                $display("%0t Stage: %b %b %h %h %h", $realtime, current_micro_word, uJump, micro_pc, op, dispatch_address);
            `endif
            clear_nmi <= 1'b0;
            case (uJump)
                UJMP_STEP:       begin
                    micro_pc <= micro_pc + 1;
                end
                UJMP_DISPATCH_1: begin
                    micro_pc <= (needs_zero_extra) ? dispatch_address : micro_pc + 1;
                end
                UJMP_DISPATCH_2: begin
                    micro_pc <= (needs_one_extra) ? dispatch_address : micro_pc + 1;
                end
                UJMP_DISPATCH_3: begin
                    micro_pc <= (needs_two_extra) ? dispatch_address : micro_pc + 1;
                end
                UJMP_SET_BREAK:  begin
                    // End of the BRK / interrupt entry sequence
                    micro_pc <= 12'h00;
                    is_irq   <= 1'b0;
                    is_nmi   <= 1'b0;
                end
                default:         begin
                    // UJMP_FETCH: instruction boundary, check for interrupts
                    if (nmi_pending) begin
                        `ifdef SIM
                            $display("%0t NMI taken!", $realtime);
                        `endif
                        micro_pc  <= 12'h010;
                        is_nmi    <= 1'b1;
                        clear_nmi <= 1'b1;   // acknowledge: a new edge can latch again
                    end else if (irq_active && !irq_mask) begin
                        `ifdef SIM
                            $display("%0t IRQ taken!", $realtime);
                        `endif
                        micro_pc <= 12'h010;
                        is_irq   <= 1'b1;
                    end else begin
                        micro_pc <= 12'h00;
                    end
                end
            endcase
        end
    end

    // =========================================================================
    // 5. OUTPUT LOGIC (Combinational slicing)
    // =========================================================================
    assign alu_op        = current_micro_word[24:21];
    assign set_addr_c    = current_micro_word[20];
    assign flags_opcode  = current_micro_word[19];
    assign flags_ctl_c   = current_micro_word[18];
    assign flags_ctl_nz  = current_micro_word[17];
    assign al_inc        = current_micro_word[16];
    assign zp_clr_set    = current_micro_word[15];
    assign dec_sp        = current_micro_word[14];
    assign pc_op         = current_micro_word[13:12];
    assign read_reg_sel1 = current_micro_word[11:8];
    assign read_reg_sel2 = current_micro_word[7:4];
    assign write_reg_sel = current_micro_word[3:0];
    assign mem_read_en = (read_reg_sel1 == REG_MEM || read_reg_sel2 == REG_MEM) ? 1 : 0;
    assign mem_write_en = write_reg_sel == REG_MEM ? 1 : 0;
endmodule
